 proposal:=jsonb_set(request,'{mutationId}','"88000000-0000-4000-8000-000000000005"');proposal:=jsonb_set(proposal,'{changes,rows,0,value,action}','"exclude"');
 result:=public.travel_life_history('correction-propose',proposal);if result->>'status' is distinct from 'conflict' then raise exception 'TEST_PRIVACY_COMPETING_RETAINED';end if;
 request:='{"mutationId":"88000000-0000-4000-8000-000000000006","generation":1,"expectedOwnerRevision":3,"proposalId":"88000000-0000-4000-8000-000000000005","choice":"accepted"}';
 result:=public.travel_life_history('correction-resolve',request);if result->>'status' is distinct from 'accepted' then raise exception 'TEST_PRIVACY_KEEP_ACCEPTED';end if;
