 result:=public.travel_life_history('correction-conflicts','{"page":0}');if result->>'error' is distinct from 'ACCOUNT_SESSION' or result::text like '%Synthetic%' then raise exception 'TEST_OWNER_PROPOSAL_ISOLATION';end if;
